var LOC={uk:"uk_UA",ru:"ru_RU",en:"en_US"},IDX={ru:0,en:1};
var PAT=[
 [/^Питання (\d+) з (\d+)$/,{ru:"Вопрос $1 из $2",en:"Question $1 of $2"}],
 [/^Збіг (\d+)%$/,{ru:"Совпадение $1%",en:"Match $1%"}]
];
var ATTRS=["aria-label","title","alt","placeholder"];
var cur="uk",orig=new WeakMap(),attrOrig=new WeakMap(),metaOrig=new WeakMap(),has=Object.prototype.hasOwnProperty;
function norm(s){return s.replace(/\s+/g," ").trim()}
function tr(s,lang){
 if(lang==="uk"||!s)return s;
 var m=/^(\s*)([\s\S]*?)(\s*)$/.exec(s),core=norm(m[2]);
 if(!core)return s;
 if(has.call(DICT,core))return m[1]+DICT[core][IDX[lang]]+m[3];
 for(var i=0;i<PAT.length;i++){if(PAT[i][0].test(core))return m[1]+core.replace(PAT[i][0],PAT[i][1][lang])+m[3]}
 return s;
}
function skip(n){var p=n.parentNode;return !p||p.nodeName==="SCRIPT"||p.nodeName==="STYLE"||p.nodeName==="NOSCRIPT"}
function tText(n){
 if(skip(n))return;
 var o=orig.get(n);if(o===undefined){o=n.nodeValue;orig.set(n,o)}
 var t=tr(o,cur);if(n.nodeValue!==t)n.nodeValue=t;
}
function tAttrs(el){
 for(var i=0;i<ATTRS.length;i++){
  var a=ATTRS[i];if(!el.hasAttribute||!el.hasAttribute(a))continue;
  var m=attrOrig.get(el);if(!m){m={};attrOrig.set(el,m)}
  if(!(a in m))m[a]=el.getAttribute(a);
  var t=tr(m[a],cur);if(el.getAttribute(a)!==t)el.setAttribute(a,t);
 }
}
function walk(root){
 if(!root)return;
 if(root.nodeType===3){tText(root);return}
 if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11)return;
 if(root.nodeType===1)tAttrs(root);
 var tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT,null),n;
 while((n=tw.nextNode())){if(n.nodeType===3)tText(n);else tAttrs(n)}
}
function tMeta(){
 var list=document.querySelectorAll('meta[property^="og:"],meta[name="description"],meta[name^="twitter:"]');
 for(var i=0;i<list.length;i++){
  var m=list[i],p=m.getAttribute("property")||m.getAttribute("name");
  if(p==="og:locale"){m.setAttribute("content",LOC[cur]);continue}
  var o=metaOrig.get(m);if(o===undefined){o=m.getAttribute("content")||"";metaOrig.set(m,o)}
  var t=tr(o,cur);if(m.getAttribute("content")!==t)m.setAttribute("content",t);
 }
}
