var mo=new MutationObserver(function(muts){
 if(cur==="uk")return;
 for(var i=0;i<muts.length;i++){var a=muts[i].addedNodes;for(var j=0;j<a.length;j++)walk(a[j])}
});
function sync(){
 var b=document.querySelectorAll(".lang [data-lang]");
 for(var i=0;i<b.length;i++)b[i].setAttribute("aria-pressed",b[i].getAttribute("data-lang")===cur?"true":"false");
}
function setLang(l){
 if(!LOC[l]||l===cur&&arguments[1]!==true)return;
 cur=l;
 try{localStorage.setItem("lang",l)}catch(e){}
 document.documentElement.lang=l;
 sync();walk(document.documentElement);tMeta();
 try{window.dispatchEvent(new Event("langchange"))}catch(e){}
}
document.addEventListener("click",function(e){
 var b=e.target.closest&&e.target.closest(".lang [data-lang]");
 if(b)setLang(b.getAttribute("data-lang"));
});
function init(){
 mo.observe(document.documentElement,{childList:true,subtree:true});
 var s=null;try{s=localStorage.getItem("lang")}catch(e){}
 if(s&&LOC[s]&&s!=="uk")setLang(s,true);else sync();
}

